import{_ as r,o as t,c as a,a5 as s}from"./chunks/framework.CslsFoWx.js";const o="/VendoraSystem-docs/captures/2026-11-09-archive-asynchrone-purge/01-bo-archive-en-cours.webp",c="/VendoraSystem-docs/captures/2026-11-09-archive-asynchrone-purge/02-bo-archive-prete.webp",n="/VendoraSystem-docs/captures/2026-11-09-archive-asynchrone-purge/03-bo-purges-du-detail.webp",d="/VendoraSystem-docs/captures/2026-11-09-archive-asynchrone-purge/04-bo-jet-purge.webp",f=JSON.parse('{"title":"Archive fiscale asynchrone (202) et purge tracée après 6 ans (09/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-09-archive-asynchrone-purge.md","filePath":"generated/preuves/2026-11-09-archive-asynchrone-purge.md","lastUpdated":null}'),i={name:"preuves/2026-11-09-archive-asynchrone-purge.md"};function l(u,e,p,h,g,v){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="archive-fiscale-asynchrone-202-et-purge-tracee-apres-6-ans-09-11-2026" tabindex="-1">Archive fiscale asynchrone (202) et purge tracée après 6 ans (09/11/2026) <a class="header-anchor" href="#archive-fiscale-asynchrone-202-et-purge-tracee-apres-6-ans-09-11-2026" aria-label="Permalink to &quot;Archive fiscale asynchrone (202) et purge tracée après 6 ans (09/11/2026)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-09-archive-asynchrone-purge</code> · 0 image(s) · 0 trace(s)</p><div><p>Carte Trello « P3 · Archive fiscale asynchrone (202) et purge tracée après 6 ans » — spec 15 RG-FISC-10 / -11 / -13. Écart de spec « archive synchrone » levé.</p><h2 id="ce-qui-change" tabindex="-1">Ce qui change <a class="header-anchor" href="#ce-qui-change" aria-label="Permalink to &quot;Ce qui change&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Volet</th><th>Avant</th><th>Après</th></tr></thead><tbody><tr><td><code>POST /stores/{id}/fiscal/archives</code></td><td><strong>201</strong>, archive générée dans la requête (risque d&#39;expiration sur un gros commerce)</td><td><strong>202</strong> + <code>archiveId</code>, statut <code>PENDING</code> ; génération sur un fil dédié, puis <code>READY</code> (JET <code>ARCHIVE_GENERATED</code>, <code>FiscalArchiveGenerated</code> inchangés) ou <code>FAILED</code> (motif, JET <code>ARCHIVE_FAILED</code>) ; refus immédiats inchangés (<strong>422</strong>)</td></tr><tr><td>Liste / téléchargement</td><td>pas de statut</td><td><code>status</code>, <code>requestedAt</code>, <code>error</code> ; <strong>409</strong> au téléchargement tant que <code>PENDING</code> ou si <code>FAILED</code> ; archives d&#39;avant V87 toujours <code>READY</code> et téléchargeables</td></tr><tr><td>Back-office « Conformité fiscale »</td><td>« Archive générée » immédiat</td><td>bandeau « demandée : génération en cours », ligne <strong>En cours…</strong> relue toutes les 2 s, puis empreinte + <strong>Télécharger</strong> ; ligne <strong>Échec</strong> avec le motif traduit</td></tr><tr><td>Purge du détail &gt; 6 ans</td><td>rien n&#39;était purgé</td><td>tâche quotidienne (désactivée par défaut, <code>POS_FISCAL_PURGE_ENABLED=true</code> en production) : détail <code>fiscal_sale_seal</code> purgé <strong>seulement</strong> s&#39;il est couvert par une archive scellée (empreintes revérifiées, archive postérieure à la réception), par préfixe de chaîne, dernier maillon gardé ; registre + entrée JET <code>PURGE</code> ; jamais les clôtures, le total perpétuel, les Z ni le JET</td></tr><tr><td>Trace des purges</td><td>—</td><td>sous-section <strong>Purges du détail (plus de 6 ans)</strong> + <code>GET /stores/{id}/fiscal/purges</code></td></tr></tbody></table><h2 id="preuves-vraie-stack" tabindex="-1">Preuves (vraie stack) <a class="header-anchor" href="#preuves-vraie-stack" aria-label="Permalink to &quot;Preuves (vraie stack)&quot;">​</a></h2><p>Serveur du worktree (port 8091, base Postgres dédiée <code>pos_aef5</code>, migration V87), back-office <code>ng serve</code> (4291), commerce de démo « Le Petit Bistrot (démo) » (<code>help/tools/seed/seed-demo.py</code>, 7 journées d&#39;activité). Données <strong>vieillies</strong> : les 5 premières journées (73 ventes scellées, Z n° 1 à 5) et la naissance du magasin reculées de 7 ans (2019-11-02 → 2019-11-06), puis « Générer les clôtures dues » (2 564 clôtures journalières, 84 mensuelles, 7 annuelles, chaînes et perpétuel cohérents).</p><table tabindex="0"><thead><tr><th>Capture</th><th>Scène</th></tr></thead><tbody><tr><td><img src="'+o+'" alt=""></td><td><strong>1. Archive en cours</strong> — « Générer l&#39;archive » sur 07/11 → 08/11 : réponse 202, la ligne affiche <strong>En cours…</strong> (1). Pour figer l&#39;état le temps de la capture, le verrou de génération du magasin était tenu 30 s depuis <code>psql</code> (<code>pg_advisory_lock</code>) ; la génération a repris seule à sa libération.</td></tr><tr><td><img src="'+c+'" alt=""></td><td><strong>2. Puis prête</strong> — sans recharger, la ligne (1) se complète : date, taille, empreinte, <strong>Précédente</strong> = empreinte de l&#39;archive de 2019 (chaînage) ; <strong>Télécharger</strong> (2).</td></tr><tr><td><img src="'+n+'" alt=""></td><td><strong>3. Purge tracée</strong> — serveur relancé avec <code>POS_FISCAL_PURGE_ENABLED=true</code> (horaire rapproché) : la tâche purge les 73 ventes du 02/11/2019 au 06/11/2019, couvertes par l&#39;archive 2019-11-02 → 2019-11-30 ; période (1), volumes (73 ventes, 185 lignes, 79 paiements) (2), archive de référence (3). Intégrité toujours <strong>OK</strong> (la chaîne de la caisse repart du maillon purgé).</td></tr><tr><td><img src="'+d+'" alt=""></td><td><strong>4. Entrée JET <code>PURGE</code></strong> (1) : période, volumes, archive de référence (identifiant et empreinte), « Clôtures, total perpétuel, Z et JET conservés ». Capture recadrée sur les 5 entrées les plus récentes.</td></tr></tbody></table><p>Scénarios rejouables : <code>help/tools/web/scenarios/reglages-conformite-fiscale-archive-asynchrone.json</code> et <code>reglages-conformite-fiscale-purge.json</code> (notes de préparation dans chaque fichier). Les mêmes images servent la page d&#39;aide « Conformité fiscale » (FR / EN / AR).</p><h2 id="trouve-en-chemin-corrige" tabindex="-1">Trouvé en chemin, corrigé <a class="header-anchor" href="#trouve-en-chemin-corrige" aria-label="Permalink to &quot;Trouvé en chemin, corrigé&quot;">​</a></h2><ul><li>Erreur de génération affichée avec <code>| t</code> : un message à valeurs (« Clôtures journalières manquantes (1/4) … ») restait en français en anglais / arabe → <code>| serverText</code>.</li><li>JET : les empreintes de 64 caractères débordaient de la carte → retour à la ligne (<code>overflow-wrap: anywhere</code>).</li></ul><h2 id="non-couvert" tabindex="-1">Non couvert <a class="header-anchor" href="#non-couvert" aria-label="Permalink to &quot;Non couvert&quot;">​</a></h2><ul><li>Android / iOS : non concernés (écran du back-office uniquement).</li></ul></div>',3)])])}const _=r(i,[["render",l]]);export{f as __pageData,_ as default};
